export const rainforestViews={
 'eco-rainforest-system':[['structure','Living & non-living'],['water','Follow water'],['links','People & connections']],
 'eco-rainforest-cycles':[['cycle','Gersmehl cycle'],['intact','Intact budget'],['harvest','Removal budget'],['inputs','Inputs & losses'],['web','Food-web links']],
 'eco-rainforest-adaptations':[['layers','Forest layers'],['roots','Root support'],['photo','Root reference'],['drip','Drip tips'],['animals','Animal adaptations']],
 'eco-rainforest-benefits':[['products','Foods & medicines'],['harvest','Timber & renewal'],['visitors','Recreation pressures']],
 'eco-rainforest-climate':[['stress','Heat & water stress'],['impacts','Three kinds of impact'],['feedback','Reinforcing feedback'],['limits','Evidence & uncertainty']]
};
export const rainforestRequirements=Object.fromEntries(Object.entries(rainforestViews).map(([k,vs])=>[k,vs.map(x=>x[0])]));
export const rainforestAnimated=(k,v)=>k==='eco-rainforest-system'?v==='water':k==='eco-rainforest-cycles'?['cycle','harvest','inputs'].includes(v):k==='eco-rainforest-adaptations'?v==='drip':k==='eco-rainforest-benefits'?v!=='products':k==='eco-rainforest-climate'?['stress','feedback'].includes(v):false;
const tx=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const path=(d,c='#bad3d9',w=3,extra='')=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" ${extra}/>`;
const dot=(x,y,r=6,c='#efb49f')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
const arrow=(d,c='#edb59f',w=3)=>path(d,c,w,'marker-end="url(#rfArrow)"');
const box=(x,y,w,a,b='')=>`<rect x="${x}" y="${y}" width="${w}" height="${b?66:48}" rx="12" fill="#3c596b" stroke="#adc4c9"/>`+tx(x+12,y+27,a,12)+(b?tx(x+12,y+48,b,11):'');
const svg=(b,c)=>`<svg class="geo-scene" viewBox="0 0 440 350" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><defs><marker id="rfArrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5 0 10Z" fill="#edb59f"/></marker><linearGradient id="rfWood"><stop stop-color="#b7a48c"/><stop offset="1" stop-color="#6d7f79"/></linearGradient></defs><g fill="#eef2f2" font-family="sans-serif">${b}</g></svg>`;
const wrap=(b,c)=>svg(b,c)+`<p class="geo-caption">${c}</p>`;
const tree=(x,y,h,w=45)=>`<path d="M${x-6} ${y}L${x-4} ${y-h+25}h8l2 ${h-25}Z" fill="url(#rfWood)"/><ellipse cx="${x}" cy="${y-h+20}" rx="${w}" ry="25" fill="#789b8c"/><ellipse cx="${x-10}" cy="${y-h+5}" rx="${w*.7}" ry="18" fill="#a5bca5"/>`;
const forest=()=>`<path d="M25 285Q190 270 415 290V310H25Z" fill="#927f6b"/>`+tree(95,285,205,48)+tree(180,285,250,35)+tree(265,285,175,57)+tree(335,285,195,47)+tree(145,285,80,25)+tree(295,285,65,30);
export const nutrientCases={intact:{start:{biomass:80,litter:5,soil:15},fall:8,decay:8,uptake:8,input:2,leach:2,harvest:0},harvest:{start:{biomass:80,litter:5,soil:15},fall:4,decay:5,uptake:3,input:2,leach:7,harvest:30}};
export function nutrientEnd(s){return {biomass:s.start.biomass-s.fall+s.uptake-s.harvest,litter:s.start.litter+s.fall-s.decay,soil:s.start.soil+s.decay-s.uptake+s.input-s.leach};}
export const nutrientTotal=s=>s.biomass+s.litter+s.soil;
export function rainforestEvidence(){const b=tx(20,27,'NUTRIENT TRANSFERS · LABELLED MODEL',14)+`<circle cx="220" cy="105" r="52" fill="#7e9c8b"/><circle cx="110" cy="240" r="34" fill="#a5937c"/><circle cx="330" cy="240" r="40" fill="#658b9e"/>`+tx(188,109,'Biomass',14)+tx(91,244,'Litter',14)+tx(316,244,'Soil',14)+arrow('M185 145L128 203')+arrow('M149 240H282')+arrow('M316 198L252 148')+arrow('M365 260L405 300')+tx(130,172,'A',16)+tx(214,225,'B',16)+tx(302,170,'C',16)+tx(385,272,'D',16)+tx(20,330,'Arrows show direction; sizes are schematic',12);return wrap(b,'A–D nutrient-flow diagram. Three stores and one outward arrow. Schematic relative sizes,not measured quantities or a food-web energy diagram.');}
export function buttressReference(){return `<figure style="margin:0"><img src="./geography/images/rainforest-buttress-v1.png" width="1536" height="1024" style="width:100%;height:auto;border-radius:12px" alt="AI-generated illustration of a large rainforest trunk with wide triangular woody buttress flanges spreading across a leaf-littered forest floor."><figcaption class="geo-caption">AI-generated structural illustration · generic rainforest tree,not an authenticated photograph or named location. Notice the wide above-ground flanges; compare the labelled support diagram. Shapes and species vary.</figcaption></figure>`;}
export function rainforestScene(k,selected,t=0){if(!rainforestViews[k])return '';const v=rainforestRequirements[k].includes(selected)?selected:rainforestRequirements[k][0];t=rainforestAnimated(k,v)?Math.min(1,Math.max(0,Number(t)||0)):0;let b='',c='';
if(k==='eco-rainforest-system'){
 if(v==='structure'){b=tx(20,28,'A LIVING SYSTEM IN A PHYSICAL ENVIRONMENT',13)+forest()+tx(25,60,'Light',12)+tx(315,55,'Rain / warmth',12)+tx(25,330,'Plants · animals · microbes · people ↔ soil · water · air',11);c='A schematic forest combines biotic organisms and abiotic light,water,temperature and mineral conditions. Soil includes living organisms too. Heights and tree forms are illustrative,not a measured forest transect; the canopy limits light reaching many understorey plants.';}
 else if(v==='water'){b=tx(20,28,'TRACE WATER,NOT WATER CREATION',14)+forest()+arrow('M60 55V110')+arrow('M280 170V245')+arrow('M60 295H120')+arrow('M370 230V75');for(let i=0;i<6;i++)b+=dot(40+i*60,65+150*((t+i/6)%1),3,'#c1e3ec');b+=tx(25,105,'Interception',11)+tx(275,170,'Throughfall',11)+tx(25,313,'Infiltration',11)+tx(280,335,'Transpiration ↑',11);c='Rain is intercepted or reaches soil by throughfall/stemflow; some water infiltrates,percolates or runs off. Roots take up water and transpiration returns vapour to the air. Dots illustrate pathways,not equal volumes or measured speeds; evaporated moisture may contribute to regional rainfall. This is not a closed water balance.';}
 else{b=tx(20,28,'CONNECTIONS INCLUDE PEOPLE',15)+box(25,75,180,'Plants / animal partners','Food,pollination,dispersal')+box(235,75,180,'Soil / water / climate','Growth conditions')+box(95,235,250,'People and livelihoods','Knowledge,use and management')+arrow('M210 100H227')+arrow('M280 150L245 225')+arrow('M150 225L115 150')+tx(25,330,'Many local and Indigenous roles; no single impact',12);c='Selected relationships show interdependence. Communities have varied knowledge,rights,livelihoods and impacts; they are not external to the ecosystem or uniformly a driver of damage. Links are illustrative,not a complete network or a quantitative impact comparison.';}
}
if(k==='eco-rainforest-cycles'){
 if(v==='web'){b=tx(20,28,'ENERGY TRANSFER · FOOD → CONSUMER',14)+box(25,75,155,'Leaves / fruit')+box(250,75,165,'Herbivores')+box(250,195,165,'Predators')+box(25,250,185,'Decomposers')+arrow('M190 100H240')+arrow('M332 132V185')+arrow('M105 135V240')+arrow('M285 265L220 275')+tx(25,330,'Dead material → decomposers; energy dissipates as heat',11);c='Selected food-web energy links: plants to herbivores to predators,and dead remains to decomposers. Arrowheads point towards the recipient of energy. Nutrients can be recycled through soil,while energy is dissipated as heat. Pollination and seed dispersal are other interdependencies,not all represented by feeding arrows.';}
 else if(v==='inputs'){b=tx(20,28,'THE SYSTEM HAS INPUTS AND OUTPUTS',14)+box(95,125,250,'Biomass + litter + soil')+box(25,55,180,'Rain / weathering inputs')+box(235,235,180,'Leaching / harvest exports')+arrow('M125 110L165 118')+arrow('M300 180L325 225')+dot(125+40*t,110+8*t)+dot(300+25*t,180+45*t)+tx(25,325,'Internal transfers redistribute; external flows change total',11);c='Rainfall deposition and rock weathering can add nutrients; leaching and harvested material remove nutrients from the chosen ecosystem boundary. The inputs and outputs are schematic,not equal measured rates. A nutrient cycle does not mean the system is sealed or has no losses.';}
 else if(v==='cycle'){const stage=Math.min(2,Math.floor(t*3)),pts=[[185,145,128,203],[149,240,282,240],[316,198,252,148]],p=pts[stage],u=t*3-stage;b=tx(20,28,'GERSMEHL · STORES AND TRANSFERS',14)+`<circle cx="220" cy="105" r="52" fill="#7e9c8b"/><circle cx="110" cy="240" r="30" fill="#a5937c"/><circle cx="330" cy="240" r="36" fill="#658b9e"/>`+tx(188,109,'Biomass',14)+tx(91,244,'Litter',14)+tx(316,244,'Soil',14)+arrow('M185 145L128 203')+arrow('M149 240H282')+arrow('M316 198L252 148')+tx(35,165,'Litterfall',11)+tx(170,225,'Decomposition',11)+tx(295,160,'Uptake',11)+dot(p[0]+(p[2]-p[0])*u,p[1]+(p[3]-p[1])*u)+tx(25,330,'Circle: nutrient store · arrow: nutrient transfer',12);c='Follow biomass → litter by litterfall → soil by decomposition → biomass by uptake. Circle areas and arrow widths are schematic,not universal percentages or exact rates. Warm,moist,aerated conditions often support rapid cycling; external inputs and losses exist but are shown separately. Energy is not being recycled by these arrows.';}
 else{const s=nutrientCases[v==='harvest'?'harvest':'intact'],e=nutrientEnd(s),a=s.start; b=tx(20,28,v==='harvest'?'INVENTED BUDGET · VEGETATION REMOVAL':'INVENTED BUDGET · INTACT COMPARISON',13);['biomass','litter','soil'].forEach((key,i)=>{const x=45+i*135,val=a[key]+(e[key]-a[key])*t,h=val*1.7;b+=`<rect x="${x}" y="${260-h}" width="85" height="${h}" rx="6" fill="${['#a7bda8','#c2aa8c','#94bdcb'][i]}"/>`+tx(x,285,key[0].toUpperCase()+key.slice(1),12)+tx(x,308,a[key]+' → '+e[key],12);});b+=tx(25,65,`Start100 + input${s.input} − leach${s.leach} − harvest${s.harvest}`,12)+tx(25,335,'End total: '+nutrientTotal(e)+' nutrient units',13);c=`Invented one-period nutrient units,not rainforest measurements. Start biomass80,litter5,soil15. Litterfall${s.fall},decomposition${s.decay},uptake${s.uptake};input${s.input},leaching${s.leach},harvest${s.harvest}. End biomass${e.biomass},litter${e.litter},soil${e.soil},total${nutrientTotal(e)}. Bars interpolate start/end balances,not independent flow observations;loop resets the same example. Nutrient proportions vary by element,soil and forest.`;}
}
if(k==='eco-rainforest-adaptations'){
 if(v==='photo')return buttressReference();
 if(v==='layers'){b=tx(20,28,'LIGHT AND HABITAT CHANGE WITH HEIGHT',14)+forest();for(const[y,s]of[[55,'Emergent'],[135,'Canopy'],[220,'Understorey'],[295,'Forest floor']])b+=path(`M25 ${y}H415`,'#d9d3bf',1,'stroke-dasharray="4 5"')+tx(305,y-8,s,12);b+=tx(25,335,'Different light,food and shelter → different niches',12);c='Simplified emergent,canopy,understorey and forest-floor layers. Tree heights,gaps and density vary;these are not rigid floors or a scale survey. Habitat complexity,tropical growing conditions and evolutionary history help explain biodiversity,not rainfall alone.';}
 else if(v==='roots'){b=tx(20,28,'BUTTRESS ROOTS · A WIDE SUPPORT BASE',14)+`<path d="M195 60L190 205 70 285 170 267 205 225 218 290 250 290 236 215 365 285 285 220 245 180 240 60Z" fill="url(#rfWood)" stroke="#c9b99e" stroke-width="2"/>`+path('M205 225L218 290M236 215L285 220M190 205L170 267','#607a74',3)+path('M25 295H415','#c1b7a2',4)+tx(25,325,'Above-ground woody flanges support some tall trees',12);c='Buttress roots widen the base of some tall rainforest trees with shallow root systems. The diagram highlights mechanical support,not a deep taproot or a feature of every rainforest plant. Shape and dimensions vary; compare the illustrative root reference without treating it as a named species or site record.';}
 else if(v==='drip'){b=tx(20,28,'DRIP TIP · WATER LEAVES THE SURFACE',14)+`<path d="M75 95Q235 50 355 250Q170 265 75 95Z" fill="#91af95" stroke="#c5d3b6" stroke-width="2"/>`+path('M80 100Q210 180 355 250','#d4dfbe',3)+dot(90+265*t,105+145*t,7,'#b6dce6')+dot(355,250+45*t,5,'#b6dce6')+tx(25,330,'Pointed tip encourages drainage; not water absorption',12);c='A symbolic water drop drains towards a pointed leaf tip. Some rainforest leaves have drip tips that help shed surface water;not every species does. Droplet routes and timing are illustrative,not measured fluid dynamics. Reduced surface wetness can help limit fungal growth and keep leaf surfaces functioning.';}
 else{b=tx(20,28,'FEATURE → FUNCTION,NOT ONE UNIVERSAL BODY',13)+box(25,65,185,'Grasping,strong limbs','Climb and hold branches')+box(230,65,185,'Relatively short wings','Manoeuvre in forest')+box(25,195,185,'Shaped beaks','Reach / process food')+box(230,195,185,'Camouflage','Reduce detection')+path('M60 155q30-25 60 0m-30-7v30','#c7b69f',5)+path('M270 155q25-30 45 0q25-30 45 0','#c0d1d7',5)+tx(25,330,'Examples vary by species and background',12);c='Examples: grasping limbs in arboreal mammals;relatively short wings in harpy eagles;fruit-reaching or processing beaks in birds;leaf/bark-like camouflage. These are inherited adaptations,not changes individuals choose. Different species have different traits;camouflage depends on background and observer.';}
}
if(k==='eco-rainforest-benefits'){
 if(v==='products'){b=tx(20,28,'EXAMPLES OF GOODS AND SERVICES',14)+box(25,75,185,'Foodstuffs','Brazil nuts / fruit / cacao')+box(230,75,185,'Medicines','Cinchona → quinine')+box(25,210,185,'Timber','Building wood / income')+box(230,210,185,'Recreation','Guided forest experiences')+tx(25,330,'Origin,production and access differ between products',11);c='Food and material products are goods;recreation is an experiential service. Cinchona originates in tropical montane forests,not every lowland rainforest;its compounds informed tested medicines. Do not consume bark or wild plants as a treatment. Forest-origin crops may now be farmed outside intact forest. Sources:Kew,ITTO.';}
 else if(v==='harvest'){b=tx(20,28,'SAME START · COMPARE WOOD REMOVAL',14);for(let i=0;i<2;i++){const x=45+i*205,start=100,end=i?70:100,val=start+(end-start)*t;b+=tx(x,80,i?'More than regrowth':'Matched by regrowth',12)+`<rect x="${x}" y="${280-val*1.6}" width="130" height="${val*1.6}" rx="8" fill="${i?'#efb49f':'#aec4ac'}"/>`+tx(x,305,'100 → '+end+' wood units',12);}c='Invented one-period wood-stock comparison:both start100 and regrow10;one removes10,the other40,so endpoints100 and70. Bars interpolate net change,not actual trees or nutrient units. Sustained wood volume alone does not establish biodiversity protection,rights,road impacts or fair benefit sharing.';}
 else{const high=t>.5;b=tx(20,28,'RECREATION BENEFITS NEED MANAGEMENT',14)+box(25,65,180,'Guides / visitors','Income and experiences')+box(235,65,180,'Wildlife / paths','Disturbance and wear')+path('M45 240Q200 130 395 260','#bcae91',18)+dot(45+350*t,240-50*Math.sin(t*Math.PI),8)+tx(25,315,'Manage routes,waste,group sizes and community benefits',11);c='A symbolic visitor follows a route. Guiding and recreation can support livelihoods while traffic,waste or disturbance can harm habitats. This is not an observed visitor-impact rate or a rule that tourism always conserves forests. Decisions and benefits should involve local communities;monitor ecological effects.';}
}
if(k==='eco-rainforest-climate'){
 if(v==='stress'){b=tx(20,28,'HEAT / DRYING → WATER AND GROWTH STRESS',13)+forest()+dot(385,75,25,'#e9be83')+`<ellipse cx="70" cy="270" rx="${35-20*t}" ry="10" fill="#84b6c8"/><path d="M335 210q25 ${-30+24*t} 50 0" fill="none" stroke="#eac0a4" stroke-width="7"/>`+tx(25,330,'Stomatal closure can limit water loss and CO₂ entry',12);c='Conceptual heat and reduced water availability can lead to stomatal closure,lower photosynthesis and growth stress. Increasing evaporative demand is not the same as unlimited actual evaporation when soil is dry. Curves/dimensions and timing are symbolic,not a measured leaf response or rainforest forecast.';}
 else if(v==='impacts'){b=tx(20,28,'STRUCTURE · FUNCTIONING · BIODIVERSITY',13)+box(25,65,390,'Structure: canopy gaps / altered vegetation')+box(25,155,390,'Functioning: carbon,water,nutrient processes')+box(25,245,390,'Biodiversity: differing species responses')+tx(25,335,'These interact but are not interchangeable measures',11);c='Tree loss can open gaps and change microclimate,ecological processes and species composition. Some organisms respond differently or move;others cannot. Fire risk interacts with drought,fragmentation and ignition sources. These are possible connected impacts,not evidence that every forest or species changes identically.';}
 else if(v==='feedback'){const pts=[[100,110,330,110],[330,125,330,235],[315,250,110,250],[95,235,95,130]],stage=Math.min(3,Math.floor(t*4)),u=t*4-stage,p=pts[stage];b=tx(20,28,'REINFORCING FEEDBACK · POSSIBLE PATHWAY',13)+box(25,60,180,'Warming / drying')+box(235,60,180,'Tree stress / loss')+box(235,235,180,'Carbon release / less','Moisture recycling')+box(25,235,180,'Greater warming /','Regional drying risk')+arrow('M210 86H225')+arrow('M325 115V225')+arrow('M225 265H215')+arrow('M110 225V118')+dot(p[0]+(p[2]-p[0])*u,p[1]+(p[3]-p[1])*u)+tx(25,335,'Feedback amplifies risk; it does not date a collapse',11);c='Tree loss can release carbon through decay/burning and reduce moisture recycling,reinforcing warming or drying. Links operate at different spatial scales and speeds;not all carbon is released instantly. The loop is a mechanism illustration,not inevitable runaway change,a measured timeline or one universal threshold.';}
 else{b=tx(20,28,'ASK WHAT THE EVIDENCE CAN ESTABLISH',14)+box(25,65,390,'Observations: change at specified places / dates')+box(25,155,390,'Mechanisms: plausible causal connections')+box(25,245,390,'Projections: scenarios + models + uncertainty')+tx(25,335,'CO₂ effects also depend on heat,water and nutrients',11);c='One dry event does not by itself prove a long-term climate trend. Future climate and ecosystem responses depend on emissions,land use,adaptation and interacting constraints. HigherCO₂ cannot be assumed to cancel heat or water stress. Source:Met Office Amazon climate-risk assessment;no exact collapse date is claimed.';}
}
return wrap(b,c);
}
